static const char *mangle_base(const char *s, unsigned *base) {
        const char *k;

        assert(s);
        assert(base);

        /* Base already explicitly specified, then don't do anything. */
        if (SAFE_ATO_MASK_FLAGS(*base) != 0)
                return s;

        /* Support Python 3 style "0b" and 0x" prefixes, because they truly make sense, much more than C's "0" prefix for octal. */
        k = STARTSWITH_SET(s, "0b", "0B");
        if (k) {
                *base = 2 | (*base & SAFE_ATO_ALL_FLAGS);
                return k;
        }

        k = STARTSWITH_SET(s, "0o", "0O");
        if (k) {
                *base = 8 | (*base & SAFE_ATO_ALL_FLAGS);
                return k;
        }

        return s;
}


int safe_atou_full(const char *s, unsigned base, unsigned *ret_u) {
        char *x = NULL;
        unsigned long l;

        assert(s);
        assert(SAFE_ATO_MASK_FLAGS(base) <= 16);

        /* strtoul() is happy to parse negative values, and silently converts them to unsigned values without
         * generating an error. We want a clean error, hence let's look for the "-" prefix on our own, and
         * generate an error. But let's do so only after strtoul() validated that the string is clean
         * otherwise, so that we return EINVAL preferably over ERANGE. */

        if (FLAGS_SET(base, SAFE_ATO_REFUSE_LEADING_WHITESPACE) &&
            strchr(WHITESPACE, s[0]))
                return -EINVAL;

        s += strspn(s, WHITESPACE);

        if (FLAGS_SET(base, SAFE_ATO_REFUSE_PLUS_MINUS) &&
            IN_SET(s[0], '+', '-'))
                return -EINVAL; /* Note that we check the "-" prefix again a second time below, but return a
                                 * different error. I.e. if the SAFE_ATO_REFUSE_PLUS_MINUS flag is set we
                                 * blanket refuse +/- prefixed integers, while if it is missing we'll just
                                 * return ERANGE, because the string actually parses correctly, but doesn't
                                 * fit in the return type. */

        if (FLAGS_SET(base, SAFE_ATO_REFUSE_LEADING_ZERO) &&
            s[0] == '0' && !streq(s, "0"))
                return -EINVAL; /* This is particularly useful to avoid ambiguities between C's octal
                                 * notation and assumed-to-be-decimal integers with a leading zero. */

        s = mangle_base(s, &base);

        errno = 0;
        l = strtoul(s, &x, SAFE_ATO_MASK_FLAGS(base) /* Let's mask off the flags bits so that only the actual
                                                      * base is left */);
        if (errno > 0)
                return -errno;
        if (!x || x == s || *x != 0)
                return -EINVAL;
        if (l != 0 && s[0] == '-')
                return -ERANGE;
        if ((unsigned long) (unsigned) l != l)
                return -ERANGE;

        if (ret_u)
                *ret_u = (unsigned) l;

        return 0;
}


int safe_atou8_full(const char *s, unsigned base, uint8_t *ret) {
        unsigned u;
        int r;

        assert(ret);

        r = safe_atou_full(s, base, &u);
        if (r < 0)
                return r;
        if (u > UINT8_MAX)
                return -ERANGE;

        *ret = (uint8_t) u;
        return 0;
}


static inline int safe_atou8(const char *s, uint8_t *ret) { return safe_atou8_full(s, 0, ret); }

int safe_atoi(const char *s, int *ret_i) {
        unsigned base = 0;
        char *x = NULL;
        long l;

        assert(s);

        s += strspn(s, WHITESPACE);
        s = mangle_base(s, &base);

        errno = 0;
        l = strtol(s, &x, base);
        if (errno > 0)
                return -errno;
        if (!x || x == s || *x != 0)
                return -EINVAL;
        if ((long) (int) l != l)
                return -ERANGE;

        if (ret_i)
                *ret_i = (int) l;

        return 0;
}


int signal_from_string(const char *s) {
        const char *p;
        int signo, r;

        /* Check that the input is a signal number. */
        if (safe_atoi(s, &signo) >= 0) {
                if (SIGNAL_VALID(signo))
                        return signo;
                else
                        return -ERANGE;
        }

        /* Drop "SIG" prefix. */
        if (startswith(s, "SIG"))
                s += 3;

        /* Check that the input is a signal name. */
        signo = static_signal_from_string(s);
        if (signo > 0)
                return signo;

        /* Check that the input is RTMIN or
         * RTMIN+n (0 <= n <= SIGRTMAX-SIGRTMIN). */
        p = startswith(s, "RTMIN");
        if (p) {
                if (*p == '\0')
                        return SIGRTMIN;
                if (*p != '+')
                        return -EINVAL;

                r = safe_atoi(p, &signo);
                if (r < 0)
                        return r;

                if (signo < 0 || signo > SIGRTMAX - SIGRTMIN)
                        return -ERANGE;

                return signo + SIGRTMIN;
        }

        /* Check that the input is RTMAX or
         * RTMAX-n (0 <= n <= SIGRTMAX-SIGRTMIN). */
        p = startswith(s, "RTMAX");
        if (p) {
                if (*p == '\0')
                        return SIGRTMAX;
                if (*p != '-')
                        return -EINVAL;

                r = safe_atoi(p, &signo);
                if (r < 0)
                        return r;

                if (signo > 0 || signo < SIGRTMIN - SIGRTMAX)
                        return -ERANGE;

                return signo + SIGRTMAX;
        }

        return -EINVAL;
}


int exit_status_from_string(const char *s) {
        uint8_t val;
        int r;

        for (size_t i = 0; i < ELEMENTSOF(exit_status_mappings); i++)
                if (streq_ptr(s, exit_status_mappings[i].name))
                        return i;

        r = safe_atou8(s, &val);
        if (r < 0)
                return r;

        return val;
}


const char* exit_status_to_string(int code, ExitStatusClass class) {
        if (code < 0 || (size_t) code >= ELEMENTSOF(exit_status_mappings))
                return NULL;
        return class & exit_status_mappings[code].class ? exit_status_mappings[code].name : NULL;
}


const char* exit_status_class(int code) {
        if (code < 0 || (size_t) code >= ELEMENTSOF(exit_status_mappings))
                return NULL;

        switch (exit_status_mappings[code].class) {
        case EXIT_STATUS_LIBC:
                return "libc";
        case EXIT_STATUS_SYSTEMD:
                return "systemd";
        case EXIT_STATUS_LSB:
                return "LSB";
        case EXIT_STATUS_BSD:
                return "BSD";
        default: return NULL;
        }
}


bool is_clean_exit(int code, int status, ExitClean clean, const ExitStatusSet *success_status) {
        if (code == CLD_EXITED)
                return status == 0 ||
                       (success_status &&
                        bitmap_isset(&success_status->status, status));

        /* If a daemon does not implement handlers for some of the signals, we do not consider this an
         * unclean shutdown */
        if (code == CLD_KILLED)
                return (clean == EXIT_CLEAN_DAEMON && IN_SET(status, SIGHUP, SIGINT, SIGTERM, SIGPIPE)) ||
                       (success_status &&
                        bitmap_isset(&success_status->signal, status));

        return false;
}


bool exit_status_set_test(const ExitStatusSet *x, int code, int status) {
        if (code == CLD_EXITED && bitmap_isset(&x->status, status))
                return true;

        if (IN_SET(code, CLD_KILLED, CLD_DUMPED) && bitmap_isset(&x->signal, status))
                return true;

        return false;
}


typedef enum { SERVICE_SIMPLE, SERVICE_EXEC, SERVICE_FORKING, SERVICE_ONESHOT, SERVICE_DBUS, SERVICE_NOTIFY, SERVICE_NOTIFY_RELOAD, SERVICE_IDLE } ServiceType;
typedef enum { SERVICE_RESTART_NO, SERVICE_RESTART_ON_SUCCESS, SERVICE_RESTART_ON_FAILURE, SERVICE_RESTART_ON_ABNORMAL, SERVICE_RESTART_ON_WATCHDOG, SERVICE_RESTART_ON_ABORT, SERVICE_RESTART_ALWAYS } ServiceRestart;
typedef enum { SERVICE_SUCCESS, SERVICE_FAILURE_RESOURCES, SERVICE_FAILURE_PROTOCOL, SERVICE_FAILURE_TIMEOUT, SERVICE_FAILURE_EXIT_CODE, SERVICE_FAILURE_SIGNAL, SERVICE_FAILURE_CORE_DUMP, SERVICE_FAILURE_WATCHDOG, SERVICE_FAILURE_START_LIMIT_HIT, SERVICE_FAILURE_OOM_KILL, SERVICE_SKIP_CONDITION } ServiceResult;
typedef struct { struct { int code, status; } main_exec_status; ExitStatusSet restart_prevent_status, restart_force_status; ServiceType type; ServiceResult result; ServiceRestart restart; bool forbid_restart; } Service;

bool service_shall_restart(Service *s, const char **reason) {
        assert(s);
        assert(reason);

        /* Don't restart after manual stops */
        if (s->forbid_restart) {
                *reason = "manual stop";
                return false;
        }

        /* Never restart if this is configured as special exception */
        if (exit_status_set_test(&s->restart_prevent_status, s->main_exec_status.code, s->main_exec_status.status)) {
                *reason = "prevented by exit status";
                return false;
        }

        /* Restart if the exit code/status are configured as restart triggers */
        if (exit_status_set_test(&s->restart_force_status,  s->main_exec_status.code, s->main_exec_status.status)) {
                /* Don't allow Type=oneshot services to restart on success. Note that Restart=always/on-success
                 * is already rejected in service_verify. */
                if (s->type == SERVICE_ONESHOT && s->result == SERVICE_SUCCESS) {
                        *reason = "service type and exit status";
                        return false;
                }

                *reason = "forced by exit status";
                return true;
        }

        *reason = "restart setting";
        switch (s->restart) {

        case SERVICE_RESTART_NO:
                return false;

        case SERVICE_RESTART_ALWAYS:
                return s->result != SERVICE_SKIP_CONDITION;

        case SERVICE_RESTART_ON_SUCCESS:
                return s->result == SERVICE_SUCCESS;

        case SERVICE_RESTART_ON_FAILURE:
                return !IN_SET(s->result, SERVICE_SUCCESS, SERVICE_SKIP_CONDITION);

        case SERVICE_RESTART_ON_ABNORMAL:
                return !IN_SET(s->result, SERVICE_SUCCESS, SERVICE_FAILURE_EXIT_CODE, SERVICE_SKIP_CONDITION);

        case SERVICE_RESTART_ON_WATCHDOG:
                return s->result == SERVICE_FAILURE_WATCHDOG;

        case SERVICE_RESTART_ON_ABORT:
                return IN_SET(s->result, SERVICE_FAILURE_SIGNAL, SERVICE_FAILURE_CORE_DUMP);

        default:
                assert_not_reached();
        }
}


/* Driver for the copied systemd functions (scripts/ref/svc_ref_build.py).
 * Reads one tab-separated command per line, prints one answer per line:
 *   es WORD              exit_status_from_string
 *   name N               exit_status_to_string(N, FULL) and exit_status_class(N)
 *   sig WORD             signal_from_string
 *   set RVALUE           config_parse_set_status's sets ("s:..;g:..")
 *   clean CODE STATUS MODE SET   is_clean_exit (SET "-" = NULL)
 *   result TYPE CODE STATUS SET  service_sigchld_event's result for the
 *                        main process (clean mode daemon unless oneshot)
 *   restart RESTART TYPE RESULT CODE STATUS PREVENT FORCE FORBID
 *                        service_shall_restart: "1 reason" / "0 reason"
 * CODE is exited, killed or dumped. A set's words are split at WHITESPACE
 * as extract_first_word() does for words without quotes or backslashes. */
static const char *const restarts[] = { "no", "on-success", "on-failure", "on-abnormal", "on-watchdog", "on-abort", "always" };
static const char *const types[] = { "simple", "exec", "forking", "oneshot", "dbus", "notify", "notify-reload", "idle" };
static const char *const results[] = { "success", "resources", "protocol", "timeout", "exit-code", "signal", "core-dump", "watchdog", "start-limit-hit", "oom-kill", "condition" };
static int find(const char *const *t, size_t n, const char *s) { for (size_t i = 0; i < n; i++) if (streq(t[i], s)) return (int) i; abort(); }
static int code_of(const char *s) { return streq(s, "exited") ? CLD_EXITED : streq(s, "killed") ? CLD_KILLED : streq(s, "dumped") ? CLD_DUMPED : (abort(), 0); }
static void parse_set(const char *rvalue, ExitStatusSet *x) {
        memset(x, 0, sizeof *x);
        char buf[4096]; snprintf(buf, sizeof buf, "%s", rvalue);
        for (char *w = strtok(buf, WHITESPACE); w; w = strtok(NULL, WHITESPACE)) {
                int r = exit_status_from_string(w);
                if (r >= 0) { bitmap_set(&x->status, r); continue; }
                r = signal_from_string(w);
                if (r < 0) continue;
                bitmap_set(&x->signal, r);
        }
}
static void show_set(const ExitStatusSet *x) {
        printf("s:"); const char *sep = "";
        for (int i = 0; i < 256; i++) if (bitmap_isset(&x->status, i)) { printf("%s%d", sep, i); sep = ","; }
        printf(";g:"); sep = "";
        for (int i = 0; i < 256; i++) if (bitmap_isset(&x->signal, i)) { printf("%s%d", sep, i); sep = ","; }
        printf("\n");
}
int main(void) {
        char line[8192];
        while (fgets(line, sizeof line, stdin)) {
                line[strcspn(line, "\n")] = 0;
                char *f[10] = {0}; int n = 0;
                for (char *p = line; n < 10; ) { f[n++] = p; char *t = strchr(p, '\t'); if (!t) break; *t = 0; p = t + 1; }
                if (streq(f[0], "es")) printf("%d\n", exit_status_from_string(f[1]));
                else if (streq(f[0], "name")) { const char *a = exit_status_to_string(atoi(f[1]), EXIT_STATUS_FULL), *b = exit_status_class(atoi(f[1])); printf("%s %s\n", a ? a : "-", b ? b : "-"); }
                else if (streq(f[0], "sig")) printf("%d\n", signal_from_string(f[1]));
                else if (streq(f[0], "set")) { ExitStatusSet x; parse_set(f[1], &x); show_set(&x); }
                else if (streq(f[0], "clean")) {
                        ExitStatusSet x; parse_set(f[4], &x);
                        printf("%d\n", is_clean_exit(code_of(f[1]), atoi(f[2]), streq(f[3], "daemon") ? EXIT_CLEAN_DAEMON : EXIT_CLEAN_COMMAND, streq(f[4], "-") ? NULL : &x));
                } else if (streq(f[0], "result")) {
                        ExitStatusSet x; parse_set(f[4], &x);
                        int code = code_of(f[2]), status = atoi(f[3]);
                        ExitClean clean_mode = streq(f[1], "oneshot") ? EXIT_CLEAN_COMMAND : EXIT_CLEAN_DAEMON;
                        ServiceResult r;
                        if (is_clean_exit(code, status, clean_mode, &x)) r = SERVICE_SUCCESS;
                        else if (code == CLD_EXITED) r = SERVICE_FAILURE_EXIT_CODE;
                        else if (code == CLD_KILLED) r = SERVICE_FAILURE_SIGNAL;
                        else r = SERVICE_FAILURE_CORE_DUMP;
                        printf("%s\n", results[r]);
                } else if (streq(f[0], "restart")) {
                        Service s = {0}; const char *reason = NULL;
                        s.restart = find(restarts, ELEMENTSOF(restarts), f[1]);
                        s.type = find(types, ELEMENTSOF(types), f[2]);
                        s.result = find(results, ELEMENTSOF(results), f[3]);
                        s.main_exec_status.code = code_of(f[4]); s.main_exec_status.status = atoi(f[5]);
                        parse_set(f[6], &s.restart_prevent_status); parse_set(f[7], &s.restart_force_status);
                        s.forbid_restart = streq(f[8], "1");
                        bool r = service_shall_restart(&s, &reason);
                        printf("%d %s\n", r, reason);
                } else abort();
                fflush(stdout);
        }
        return 0;
}

